        (re.compile(r"base64\.b64decode"), "b64decode"),
        (re.compile(r"subprocess"), "subprocess"),
        (re.compile(r"id_rsa"), "id_rsa"),
        (re.compile(r"credentials"), "credentials"),
        (re.compile(r"\.env"), ".env"),
        (re.compile(r"\.npmrc"), ".npmrc"),
        (re.compile(r"CI"), "CI"),
        (re.compile(r"socket\.gethostbyname"), "gethostbyname"),
        (re.compile(r"urllib\.request"), "urllib.request"),
        (re.compile(r"requests\.post"), "requests.post")
    ]

